import { test, expect } from '@playwright/test';

test.describe('Deep Link Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com');
  });

  test('should load the home page when navigating to the root URL', async ({ page }) => {
    await page.goto('https://example.com/');
    const heading = await page.getByRole('heading', { name: /welcome/i });
    await expect(heading).toBeVisible();
  });

  test('should load the about page when navigating to the about URL', async ({ page }) => {
    await page.goto('https://example.com/about');
    const heading = await page.getByRole('heading', { name: /about us/i });
    await expect(heading).toBeVisible();
  });
});
